class StateStore {
  final Map<String, dynamic> _state = {};

  dynamic get(String key) {
    return _state[key];
  }

  void set(String key, dynamic value) {
    _state[key] = value;
  }

  Map<String, dynamic> getAll() {
    return Map.from(_state);
  }

  String describe() {
    final entries = _state.entries.map((e) => '${e.key}=${e.value}').join(', ');
    return 'State(keys: ${_state.length}): $entries';
  }
}

void main() {
  final store = StateStore();
  store.set('count', 0);
  store.set('name', 'Alice');
  print('Count: ${store.get('count')}');
  print(store.describe());
}

