class StateAggregator {
  final Map<String, dynamic> _state = {};
  final Map<String, List<Function>> _keyListeners = {};
  final List<Function> _globalListeners = [];

  StateAggregator(Map<String, dynamic> initialValues) {
    _state.addAll(initialValues);
  }

  dynamic get(String key) {
    return _state[key];
  }

  void update(String key, dynamic value) {
    if (_state[key] == value) return;
    _state[key] = value;

    final keyCallbacks = _keyListeners[key];
    if (keyCallbacks != null) {
      for (final cb in keyCallbacks) {
        cb();
      }
    }

    for (final cb in _globalListeners) {
      cb();
    }
  }

  void onChange(String key, Function callback) {
    _keyListeners.putIfAbsent(key, () => []).add(callback);
  }

  void onChangeAll(Function callback) {
    _globalListeners.add(callback);
  }

  Map<String, dynamic> snapshot() {
    return Map.from(_state);
  }

  String describe() {
    final entries = _state.entries.map((e) => '${e.key}=${e.value}').join(', ');
    return 'Aggregator($entries)';
  }
}

void main() {
  final agg = StateAggregator({'count': 0, 'name': 'Alice'});
  final events = <String>[];

  agg.onChange('count', () => events.add('count'));
  agg.onChangeAll(() => events.add('global'));

  agg.update('count', 1);
  agg.update('name', 'Bob');

  print('Events: $events');
  print(agg.describe());
}
